WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date DESC NULLS LAST, id) AS rank_in_group FROM store_sales QUALIFY rank_in_group = 1) SELECT s.id, s.store_id, s.product_id, s.sale_date, s.units, s.rank_in_group, (SELECT MAX(x.units) FROM store_sales x WHERE x.product_id = s.product_id) AS max_store_sale_units FROM latest s ORDER BY max_store_sale_units DESC NULLS FIRST;
